// NewCreateRequestRequestBody builds the HTTP request body from the payload of
// the "createRequest" endpoint of the "mcpApproval" service.
func NewCreateRequestRequestBody(p *mcpapproval.CreateRequestPayload) *CreateRequestRequestBody {
	body := &CreateRequestRequestBody{
		TargetKind: p.TargetKind,
		Target:     p.Target,
		Note:       p.Note,
	}
	return body
}

// NewPromoteRequestBody builds the HTTP request body from the payload of the
// "promote" endpoint of the "mcpApproval" service.
func NewPromoteRequestBody(p *mcpapproval.PromotePayload) *PromoteRequestBody {
	body := &PromoteRequestBody{
		RiskPolicyBypassRequestID: p.RiskPolicyBypassRequestID,
	}
	return body
}

// NewRecordDecisionRequestBody builds the HTTP request body from the payload
// of the "recordDecision" endpoint of the "mcpApproval" service.
func NewRecordDecisionRequestBody(p *mcpapproval.RecordDecisionPayload) *RecordDecisionRequestBody {
	body := &RecordDecisionRequestBody{
		ID:               p.ID,
		Decision:         p.Decision,
		Rationale:        p.Rationale,
		ResearchReportID: p.ResearchReportID,
	}
	if p.GrantedPrincipalUrns != nil {
		body.GrantedPrincipalUrns = make([]string, len(p.GrantedPrincipalUrns))
		for i, val := range p.GrantedPrincipalUrns {
			body.GrantedPrincipalUrns[i] = val
		}
	}
	return body
}

// NewListRequestsListApprovalRequestsResultOK builds a "mcpApproval" service
// "listRequests" endpoint result from a HTTP "OK" response.
func NewListRequestsListApprovalRequestsResultOK(body *ListRequestsResponseBody) *mcpapproval.ListApprovalRequestsResult {
	v := &mcpapproval.ListApprovalRequestsResult{
		NextCursor: body.NextCursor,
	}
	v.Requests = make([]*mcpapproval.ApprovalRequestSummary, len(body.Requests))
	for i, val := range body.Requests {
		if val == nil {
			v.Requests[i] = nil
			continue
		}
		v.Requests[i] = unmarshalApprovalRequestSummaryResponseBodyToMcpapprovalApprovalRequestSummary(val)
	}

	return v
}

